    if isinstance(t, Zero):  return "0"
    if isinstance(t, Nil):   return "nil"
    if isinstance(t, Add):   return "(%s + %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sub):   return "(%s - %s)" % (show(t.a), show(t.b))
    if isinstance(t, Sum):   return "sum(%s)"   % show(t.v)
    if isinstance(t, Elem):  return "eltsub(%s,%s)" % (show(t.a), show(t.b))
    if isinstance(t, Cons):  return "cons(%s,%s)"   % (show(t.h), show(t.t))
    if isinstance(t, Claim): return t.text
    raise TypeError(t)

