def SUB_CONG(a,b):  return Thm(Sub(a.l,b.l), Sub(a.r,b.r), "sub_cong",  _h(a,b))
def SUM_CONG(a):    return Thm(Sum(a.l), Sum(a.r), "sum_cong", _h(a))
def ELEM_CONG(a,b): return Thm(Elem(a.l,b.l), Elem(a.r,b.r), "elem_cong", _h(a,b))
def CONS_CONG(a,b): return Thm(Cons(a.l,b.l), Cons(a.r,b.r), "cons_cong", _h(a,b))
