def DEF_SUM_CONS(x,xs): return Thm(Sum(Cons(x,xs)), Add(x, Sum(xs)), "def_sum_cons")
def DEF_ELEM_NIL():     return Thm(Elem(Nil(),Nil()), Nil(), "def_elem_nil")
