        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) + v
        return d
    if isinstance(t, Sub):
        d = dict(_norm(t.a))
        for k,v in _norm(t.b).items(): d[k] = d.get(k,0) - v
        return d
    return {t: 1}                       # atoms incl. Sum(...), Var, Cons(...)
