_D = {"add": Add, "sub": Sub, "sum": Sum, "eltsub": Elem, "cons": Cons}
def parse_term(s):
    toks = re.findall(r"\(|\)|[^\s()]+", s); pos = 0
    def rd():
        nonlocal pos
        tk = toks[pos]; pos += 1
        if tk == "(":
            op = toks[pos]; pos += 1; args = []
            while toks[pos] != ")": args.append(rd())
            pos += 1; return _D[op](*args)
        return {"zero": Zero, "nil": Nil}.get(tk, lambda: Var(tk))()
    t = rd(); assert pos == len(toks), "trailing tokens %r" % s
    return t

