def parse_cert(text):
    steps, goal = [], None
    pat = re.compile(r"^step\s+(\S+)\s*:\s*(\S+)\s*params=\[([^\]]*)\]\s*from=\[([^\]]*)\]\s*$")
    for ln in text.splitlines():
        ln = ln.strip()
        if ln.startswith("step "):
            m = pat.match(ln); assert m, "bad line %r" % ln
            ps = [parse_term(p) for p in m.group(3).split(",") if p.strip()]
            pr = [p.strip() for p in m.group(4).split(",") if p.strip()]
            steps.append((m.group(1), m.group(2), ps, pr))
        elif ln.startswith("goal "): goal = ln[5:].strip()
    return steps, goal

